const LEGACY='classroom-lucky-wheel-v1';
const DB='lucky-classroom-images';
// Store each image once, including images referenced from both the draft and history.
export function packState(state){const images=[],index=new Map();const pack=entry=>{if(!entry)return null;const copy={...entry};if(entry.image){let ref=index.get(entry.image.src);if(ref===undefined){ref=images.length;index.set(entry.image.src,ref);images.push(entry.image);}delete copy.image;copy.imageRef=ref;}return copy;};return {...state,_imageSchema:1,images,items:state.items.map(pack),draft:state.draft.map(pack),history:state.history.map(pack),last:pack(state.last)};}
export function unpackState(record){if(!record?._imageSchema)return record;const unpack=entry=>{if(!entry)return null;const copy={...entry};if(Number.isInteger(entry.imageRef)){const image=record.images?.[entry.imageRef];if(!image)throw new Error('Thiếu dữ liệu ảnh đã lưu.');copy.image={...image};delete copy.imageRef;}return copy;};const result={...record,items:record.items.map(unpack),draft:record.draft.map(unpack),history:record.history.map(unpack),last:unpack(record.last)};delete result.images;delete result._imageSchema;return result;}
export class TeacherStore{
 constructor(local=globalThis.localStorage,idb=globalThis.indexedDB){this.local=local;this.idb=idb;this.dbPromise=null;this.queue=Promise.resolve();this.pending=0;this.clock=Date.now();}
 open(){if(!this.idb)return Promise.reject(new Error('IndexedDB không khả dụng.'));if(!this.dbPromise)this.dbPromise=new Promise((resolve,reject)=>{const request=this.idb.open(DB,1);request.onupgradeneeded=()=>request.result.createObjectStore('sessions');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);request.onblocked=()=>reject(new Error('Kho ảnh đang bận.'));});return this.dbPromise;}
 async record(mode,value){const db=await this.open();return new Promise((resolve,reject)=>{const tx=db.transaction('sessions',mode),store=tx.objectStore('sessions'),req=value===undefined?store.get('teacher'):store.put(value,'teacher');let result;req.onsuccess=()=>{result=req.result;};tx.oncomplete=()=>resolve(result);tx.onerror=tx.onabort=()=>reject(tx.error||new Error('Không lưu được ảnh.'));});}
 async load(){let local=null,stored=null;try{local=JSON.parse(this.local.getItem(LEGACY)||'null');}catch{}try{stored=await this.record('readonly');}catch{}const chosen=(stored?._savedAt||0)>(local?._savedAt||0)?stored:local;return unpackState(chosen);}
 save(state){const record=packState({...state,_savedAt:this.clock=Math.max(Date.now(),this.clock+1)});let localOK=false;try{const json=JSON.stringify(record);if(json.length<1800000){this.local.setItem(LEGACY,json);localOK=true;}}catch{}this.pending++;const task=this.queue.catch(()=>{}).then(async()=>{let dbOK=false;try{await this.record('readwrite',record);dbOK=true;}catch{}if(!localOK&&!dbOK)throw new Error('Thiết bị chưa lưu được bộ ảnh. Hãy giữ trang mở và sao chép link để lưu lại.');});this.queue=task;task.then(()=>this.pending--,()=>this.pending--);return task;}
}
